      let t = (a += 0x6d2b79f5);
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  const rng = mulberry32(0xc0de19);
  for (let t = 0; t < 500; t++) {
    const arr = [];
    for (let i = 0; i < 19; i++) arr.push(Math.floor(rng() * 13) - 6);
    arr.sort((a, b) => a - b);
    add(arr);
  }
  const rng2 = mulberry32(0xbeef);
  for (let t = 0; t < 300; t++) {
    const len = 1 + Math.floor(rng2() * 40);
    const arr = [];
    for (let i = 0; i < len; i++) arr.push(Math.floor(rng2() * 21) - 10);
    arr.sort((a, b) => a - b);
    add(arr);
  }
  for (let n = 2; n <= 25; n++) {
    for (const v of [-6, 0, 6]) {
      for (const w of [-5, 1, 5]) {
        if (w <= v) continue;
        add(Array(1).fill(v).concat(Array(n - 1).fill(w)));
        add(Array(Math.floor(n / 2)).fill(v).concat(Array(n - Math.floor(n / 2)).fill(w)));
        add(Array(n - 1).fill(v).concat([w]));
      }
    }
  }

