    '}',
    'const TOKEN = readAll(3);',
    'function report(payload) {',
    '  try { writeSync(4, Buffer.from(JSON.stringify(payload))); } catch {}',
    '}',
    'function eq(a, b) {',
    '  if (a === b) return true;',
    '  if (!a || !b || a.length !== b.length) return false;',
    '  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;',
    '  return true;',
    '}',
    'const VECTORS = ' + JSON.stringify(vectors) + ';',
    'let dedupeSorted;',
    'try {',
    '  const mod = await import(' + JSON.stringify(submissionUrl) + ');',
    '  dedupeSorted = mod.dedupeSorted;',
    '} catch (e) {',
    '  report({ token: TOKEN, accept: false, reason: "import failed: " + String(e && e.message || e) });',
    '  process.exit(0);',
    '}',
    'if (typeof dedupeSorted !== "function") {',
    '  report({ token: TOKEN, accept: false, reason: "dedupeSorted is not a function" });',
    '  process.exit(0);',
    '}',
    'const tests = [];',
    'function test(name, fn) { tests.push([name, fn]); }',
    pinned,
    'test("parent-generated vector suite", () => {',
    '  for (let i = 0; i < VECTORS.length; i++) {',
    '    const src = VECTORS[i][0];',
    '    const input = [];',
    '    for (let j = 0; j < src.length; j++) input[j] = src[j];',
    '    const expected = VECTORS[i][1];',
    '    const got = dedupeSorted(input);',
    '    if (!eq(got, expected)) {',
    '      throw new Error("vector " + i + " len=" + src.length + " input=" + JSON.stringify(src) + " expected=" + JSON.stringify(expected) + " got=" + JSON.stringify(got));',
    '    }',
    '  }',
    '});',
    'const expectedCount = tests.length;',
    'let passed = 0;',
    'try {',
    '  for (const [, fn] of tests) {',
    '    fn();',
    '    passed++;',
    '  }',
    '} catch (e) {',
    '  report({ token: TOKEN, accept: false, reason: "test failed after " + passed + " passed: " + String(e && e.message || e), passed, expected: expectedCount });',
    '  process.exit(0);',
    '}',
    'if (passed !== expectedCount) {',
    '  report({ token: TOKEN, accept: false, reason: "incomplete suite", passed, expected: expectedCount });',
    '  process.exit(0);',
    '}',
    'report({ token: TOKEN, accept: true, reason: "all " + passed + " tests passed", passed, expected: expectedCount });',
    'process.exit(0);'
  ].join('\n');

  fs.writeFileSync(runnerPath, runnerSrc, 'utf8');

  try {
    const outcome = await new Promise((resolve) => {
      let done = false;
      let child;
      const finish = (v) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        try { if (child) child.kill('SIGKILL'); } catch {}
        resolve(v);
      };
